Index: apps/desktop/src/main/handlers.ts
===================================================================
--- apps/desktop/src/main/handlers.ts	
+++ apps/desktop/src/main/handlers.ts	
@@ -1,551 +1,558 @@
 import { basename } from "node:path";
 import { writeFile } from "node:fs/promises";
 import type { SaveDialogOptions, SaveDialogReturnValue } from "electron";
 import { z } from "zod";
 import {
   allBlockImplementations,
   BMW_DEFAULT_TEMPLATE,
   createBlockRegistry,
 } from "@reqflow/blocks";
 import {
   AuditAction,
   AuditEntityType,
   type AuditFilter,
   DECISION_TO_STATUS,
   DecisionStatus,
   emptyPipelineData,
   EvidenceLevel,
   type FieldChange,
   Priority,
   RequirementCategory,
   RequirementDecision,
   RequirementEdit,
   type RequirementFilter,
   Settings,
   type WorkflowRun,
   type WorkflowSave,
   type LlmClient,
   type WebSearch,
 } from "@reqflow/core";
 import type { AppInfo, ReqflowHandlers, SecretName } from "@reqflow/core/ipc";
 import {
   createDatabase,
   formatRequirementsCsv,
   formatRequirementsJson,
   formatRequirementsMarkdown,
   removeDemoData,
   SqliteAuditLogger,
   SqliteRequirementRepository,
   SqliteRunRepository,
   type LocalFileStore,
 } from "@reqflow/db";
 import { BlockRegistry, WorkflowExecutor } from "@reqflow/engine";
-import { createLlmClient } from "@reqflow/llm";
+import { createMastraLlmClient } from "@reqflow/llm";
 import { ReqflowError } from "./dispatch";
 import { previewBlock } from "./preview";
 import { SecretsStore } from "./secrets";
 import { loadSettings, saveSettings } from "./settings-storage";
 import { getWorkflow, listWorkflows, removeWorkflow, saveWorkflow } from "./workflow-storage";

 const RequirementFilterSchema = z
   .object({
     runId: z.string().optional(),
     status: z.array(DecisionStatus).optional(),
     category: z.array(RequirementCategory).optional(),
     priority: z.array(Priority).optional(),
     evidenceLevel: z.array(EvidenceLevel).optional(),
   })
   .optional();

 const AuditFilterSchema = z
   .object({
     entityId: z.string().optional(),
     entityType: AuditEntityType.optional(),
     actorType: z.enum(["ai", "human", "system"]).optional(),
     action: AuditAction.optional(),
     runId: z.string().optional(),
     limit: z.number().int().positive().optional(),
   })
   .optional();

 const SecretNameSchema = z.enum(["anthropic_api_key", "tavily_api_key"]);

 const ExportRequirementsSchema = z.object({
   runId: z.string().optional(),
   format: z.enum(["json", "csv", "md"]),
 });

 async function showElectronSaveDialog(opts: SaveDialogOptions): Promise<SaveDialogReturnValue> {
   try {
     const electron = await import("electron");
     if (electron.dialog) {
       return await electron.dialog.showSaveDialog(opts);
     }
   } catch {
     // fallback
   }
   return { canceled: true, filePath: "" };
 }

 export interface HandlerDeps {
   appInfo: () => AppInfo;
   files: LocalFileStore;
   /** Shows the native open dialog; resolves to the chosen path, or null when cancelled. */
   pickFile: () => Promise<string | null>;
   dataDir?: string;
   dbPath?: string;
   registry?: BlockRegistry;
   llm?: LlmClient;
   web?: WebSearch | null;
   saveDialog?: (opts: SaveDialogOptions) => Promise<SaveDialogReturnValue>;
   pushRunUpdate?: (run: WorkflowRun) => void;
   secretsStore?: SecretsStore;
 }

 export function createHandlers(deps: HandlerDeps): ReqflowHandlers {
   const info = deps.appInfo();
   const dataDir = deps.dataDir ?? info.dataDir;
   const db = createDatabase(deps.dbPath ?? (dataDir ? `${dataDir}/reqflow.db` : ":memory:"));

   // Earlier builds seeded synthetic demo data into every new database; remove what's left of it.
   const demo = removeDemoData(db);
   const demoRows = Object.values(demo).reduce((sum, n) => sum + n, 0);
   if (demoRows) console.info(`Removed ${demoRows} synthetic demo rows from the database`, demo);

   const auditLogger = new SqliteAuditLogger(db);
   const runRepo = new SqliteRunRepository(db);
   const reqRepo = new SqliteRequirementRepository(db);
   const secretsStore = deps.secretsStore ?? new SecretsStore(dataDir);

   const configuredLlm = async (settings: Settings): Promise<LlmClient> => {
     if (deps.llm) return deps.llm;
     const apiKey =
       settings.llm.provider === "anthropic"
         ? ((await secretsStore.getSecret("anthropic_api_key")) ?? undefined)
         : undefined;
-    return createLlmClient(settings.llm, { apiKey });
+    return createMastraLlmClient(settings.llm, { apiKey });
   };
   const activeLlm: LlmClient = deps.llm ?? {
     generateObject: async (request) =>
       (await configuredLlm(loadSettings(dataDir))).generateObject(request),
     generateText: async (request) =>
       (await configuredLlm(loadSettings(dataDir))).generateText(request),
   };

   const registry = deps.registry ?? createBlockRegistry();

   const executor = new WorkflowExecutor({
     registry,
     services: {
       llm: configuredLlm,
       audit: auditLogger,
       files: deps.files,
       web: deps.web ?? null,
       car: {
         async add(requirements, evidence) {
           await reqRepo.savePipelineData({
             ...emptyPipelineData(),
             ...evidence,
             requirements,
           });
         },
         async nextSeq(scope) {
           // Counts deleted requirements too (via the audit trail): ids are never reused.
           return (await reqRepo.maxSeq(`REQ-${scope.vehicleCode}-${scope.market}-`)) + 1;
         },
       },
     },
     outputStore: {
       async saveBlockOutput(runId, blockId, outputs) {
         await runRepo.saveBlockOutput(runId, blockId, outputs);
       },
       async getBlockOutput(runId, blockId) {
         return await runRepo.getBlockOutput(runId, blockId);
       },
+      async saveSplitterReview(run, blockId, outputs, event) {
+        await runRepo.saveSplitterReview(run, blockId, outputs, event);
+      },
     },
     onUpdate: (run) => {
       void runRepo.update(run).catch(() => {});
       deps.pushRunUpdate?.(run);
     },
   });

   return {
     app: { info: async () => deps.appInfo() },
     blocks: { preview: (request) => previewBlock(registry, deps.files, request) },
     templates: { list: async () => [BMW_DEFAULT_TEMPLATE] },
     workflows: {
       list: async () => listWorkflows(dataDir),
       get: async (id: string) => {
         const validatedId = z.string().min(1).parse(id);
         return getWorkflow(dataDir, validatedId);
       },
       save: async (input: WorkflowSave) => {
         const saved = saveWorkflow(dataDir, input);
         const settings = loadSettings(dataDir);
         await auditLogger.record({
           actor: {
             type: "human",
             userId: settings.review.reviewer.userId,
             name: settings.review.reviewer.name,
             role: settings.review.reviewer.role,
           },
           action: "workflow.saved",
           entityType: "workflow",
           entityId: saved.id,
           rationale: `Saved workflow "${saved.name}" v${saved.version}`,
         });
         return saved;
       },
       remove: async (id: string) => {
         const validatedId = z.string().min(1).parse(id);
         removeWorkflow(dataDir, validatedId);
       },
     },
     files: {
       import: async () => {
         const path = await deps.pickFile();
         return path ? deps.files.importFile(path) : null;
       },
     },
     runs: {
       start: async (workflowId: string) => {
         const wfId = z.string().min(1).parse(workflowId);
         const wf = getWorkflow(dataDir, wfId);
         const settings = loadSettings(dataDir);
         const startedBy = {
           type: "human" as const,
           userId: settings.review.reviewer.userId,
           name: settings.review.reviewer.name,
           role: settings.review.reviewer.role,
         };

         const initialRun = await executor.start(wf, startedBy, settings);
         await runRepo.create(initialRun);
         deps.pushRunUpdate?.(initialRun);
         return initialRun;
       },
       get: async (runId: string) => {
         const rId = z.string().min(1).parse(runId);
         try {
           return await runRepo.get(rId);
         } catch {
           throw new ReqflowError("not_found", `Run not found: ${rId}`);
         }
       },
       list: async (workflowId?: string) => {
         const wfId = workflowId ? z.string().min(1).parse(workflowId) : undefined;
         return await runRepo.list(wfId);
       },
       blockOutput: async (runId: string, blockId: string) => {
         const rId = z.string().min(1).parse(runId);
         const bId = z.string().min(1).parse(blockId);
         const outputs = await runRepo.getBlockOutput(rId, bId);
         if (!outputs) {
           throw new ReqflowError(
             "not_found",
             `No outputs found for block "${bId}" in run "${rId}"`,
           );
         }
         return outputs;
       },
       resume: async (runId: string) => {
         const rId = z.string().min(1).parse(runId);
         const run = await runRepo.get(rId);
         if (run.status !== "waiting_for_review") {
           throw new ReqflowError(
             "invalid_state",
             `Cannot resume run ${rId}: status is "${run.status}", expected "waiting_for_review"`,
           );
         }
         const resumed = await executor.resume(rId);
         await runRepo.update(resumed);
         deps.pushRunUpdate?.(resumed);
         return resumed;
       },
+      reviewSplitter: async (runId, blockId, review) => {
+        const reviewer = loadSettings(dataDir).review.reviewer;
+        return executor.reviewSplitter(z.string().startsWith("run_").parse(runId), z.string().min(1).parse(blockId), review, { type: "human", ...reviewer });
+      },
       cancel: async (runId: string) => {
         const rId = z.string().min(1).parse(runId);
         const cancelled = await executor.cancel(rId);
         await runRepo.update(cancelled);
         deps.pushRunUpdate?.(cancelled);
         return cancelled;
       },
     },
     requirements: {
       list: async (filter?: RequirementFilter) => {
         const validFilter = RequirementFilterSchema.parse(filter);
         return await reqRepo.list(validFilter);
       },
       get: async (id: string) => {
         const reqId = z.string().min(1).parse(id);
         try {
           return await reqRepo.get(reqId);
         } catch {
           throw new ReqflowError("not_found", `Requirement not found: ${reqId}`);
         }
       },
       edit: async (id: string, edit: unknown) => {
         const reqId = z.string().min(1).parse(id);
         const validEdit = RequirementEdit.parse(edit);
         const detail = await reqRepo.get(reqId);
         const current = detail.requirement;
         const settings = loadSettings(dataDir);

         const changes: FieldChange[] = [];
         const updatedFields: Record<string, unknown> = {};

         for (const [key, val] of Object.entries(validEdit)) {
           if (key === "rationale") continue;
           const currentVal = (current as Record<string, unknown>)[key];
           if (JSON.stringify(currentVal) !== JSON.stringify(val)) {
             changes.push({ path: key, before: currentVal, after: val });
             updatedFields[key] = val;
           }
         }

         const newVersion = {
           ...current,
           ...updatedFields,
           version: current.version + 1,
           updatedAt: new Date().toISOString(),
         };

         const saved = await reqRepo.saveVersion(newVersion);

         await auditLogger.record({
           actor: {
             type: "human",
             userId: settings.review.reviewer.userId,
             name: settings.review.reviewer.name,
             role: settings.review.reviewer.role,
           },
           action: "requirement.edited",
           entityType: "requirement",
           entityId: reqId,
           runId: current.runId,
           rationale: validEdit.rationale,
           changes,
         });

         return saved;
       },
       decide: async (id: string, decisionInput: unknown) => {
         const reqId = z.string().min(1).parse(id);
         const decision = RequirementDecision.parse(decisionInput);
         const detail = await reqRepo.get(reqId);
         const current = detail.requirement;
         const settings = loadSettings(dataDir);

         if (decision.decision === "challenge") {
           await auditLogger.record({
             actor: {
               type: "human",
               userId: settings.review.reviewer.userId,
               name: settings.review.reviewer.name,
               role: settings.review.reviewer.role,
             },
             action: "requirement.challenged",
             entityType: "requirement",
             entityId: reqId,
             runId: current.runId,
             rationale: decision.rationale,
             changes: [{ path: "status", before: current.status, after: "challenged" }],
           });

           const prompt = `Evaluate PM challenge on requirement ${current.id}: "${decision.rationale}".`;
           let answer = `Challenge acknowledged: Evaluated PM question "${decision.rationale}". Findings and targets re-verified.`;
           try {
             const resp = await activeLlm.generateText({ prompt });
             answer = resp.text;
           } catch {
             // fallback
           }

           const updatedReq = {
             ...current,
             status: "in_review" as const,
             uncertainties: Array.from(
               new Set([...current.uncertainties, `PM Challenge noted: ${decision.rationale}`]),
             ),
             version: current.version + 1,
             updatedAt: new Date().toISOString(),
           };

           const saved = await reqRepo.saveVersion(updatedReq);

           await auditLogger.record({
             actor: { type: "ai", component: "requirements.challenge", model: settings.llm.model },
             action: "requirement.challenge_answered",
             entityType: "requirement",
             entityId: reqId,
             runId: current.runId,
             rationale: answer,
             changes: [
               { path: "status", before: "challenged", after: "in_review" },
               {
                 path: "uncertainties",
                 before: current.uncertainties,
                 after: updatedReq.uncertainties,
               },
             ],
           });

           return saved;
         }

         const targetStatus = DECISION_TO_STATUS[decision.decision];
         const newPriority = decision.priority ?? current.priority;
         const changes: FieldChange[] = [
           { path: "status", before: current.status, after: targetStatus },
         ];

         if (decision.priority && decision.priority !== current.priority) {
           changes.push({ path: "priority", before: current.priority, after: decision.priority });
         }

         const updatedReq = {
           ...current,
           status: targetStatus,
           priority: newPriority,
           version: current.version + 1,
           updatedAt: new Date().toISOString(),
         };

         const saved = await reqRepo.saveVersion(updatedReq);

         await auditLogger.record({
           actor: {
             type: "human",
             userId: settings.review.reviewer.userId,
             name: settings.review.reviewer.name,
             role: settings.review.reviewer.role,
           },
           action: "requirement.status_changed",
           entityType: "requirement",
           entityId: reqId,
           runId: current.runId,
           rationale: decision.rationale,
           changes,
         });

         return saved;
       },
       reset: async () => {
         const { reviewer } = loadSettings(dataDir).review;
         const removed = await reqRepo.removeAll();
         for (const r of removed) {
           await auditLogger.record({
             actor: {
               type: "human",
               userId: reviewer.userId,
               name: reviewer.name,
               role: reviewer.role,
             },
             action: "requirement.deleted",
             entityType: "requirement",
             entityId: r.id,
             runId: r.runId,
             rationale: "Removed with Reset on the Car page.",
             changes: [{ path: "status", before: r.status, after: null }],
           });
         }
         return { removed: removed.length };
       },
     },
     audit: {
       list: async (filter?: unknown) => {
         const validFilter = AuditFilterSchema.parse(filter);
         return await auditLogger.list(validFilter);
       },
     },
     settings: {
       get: async () => loadSettings(dataDir),
       save: async (settingsInput) => {
         const oldSettings = loadSettings(dataDir);
         const saved = saveSettings(dataDir, settingsInput);
         const changes: FieldChange[] = [];

         for (const key of Object.keys(saved) as (keyof Settings)[]) {
           if (JSON.stringify(oldSettings[key]) !== JSON.stringify(saved[key])) {
             changes.push({ path: key, before: oldSettings[key], after: saved[key] });
           }
         }

         if (changes.length > 0) {
           await auditLogger.record({
             actor: {
               type: "human",
               userId: saved.review.reviewer.userId,
               name: saved.review.reviewer.name,
               role: saved.review.reviewer.role,
             },
             action: "settings.changed",
             entityType: "settings",
             entityId: "default",
             rationale: "Settings updated via Settings page",
             changes,
           });
         }

         return saved;
       },
       secrets: async () => secretsStore.getStatus(),
       setSecret: async (nameInput: unknown, valueInput: unknown) => {
         const name = SecretNameSchema.parse(nameInput);
         const value = z.string().nullable().parse(valueInput);
         await secretsStore.setSecret(name, value);
         return await secretsStore.getStatus();
       },
     },
     exports: {
       requirements: async (optsInput: unknown) => {
         const opts = ExportRequirementsSchema.parse(optsInput);
         const reqs = await reqRepo.list(opts.runId ? { runId: opts.runId } : undefined);
         const currentSettings = loadSettings(dataDir);

         let content: string;
         if (opts.format === "csv") {
           content = formatRequirementsCsv(reqs);
         } else if (opts.format === "md") {
           content = formatRequirementsMarkdown(
             reqs,
             `BMW ${currentSettings.defaultScope.vehicleLine} Requirements`,
           );
         } else {
           content = formatRequirementsJson(reqs);
         }

         const saveFn = deps.saveDialog ?? showElectronSaveDialog;
         const res = await saveFn({
           title: "Export Requirements",
           defaultPath: `bmw_requirements_${opts.runId ?? "all"}.${opts.format}`,
           filters: [
             { name: opts.format.toUpperCase(), extensions: [opts.format] },
             { name: "All Files", extensions: ["*"] },
           ],
         });

         if (res.canceled || !res.filePath) {
           return null;
         }

         await writeFile(res.filePath, content, "utf8");

         await auditLogger.record({
           actor: {
             type: "human",
             userId: currentSettings.review.reviewer.userId,
             name: currentSettings.review.reviewer.name,
             role: currentSettings.review.reviewer.role,
           },
           action: "export.created",
           entityType: "export",
           entityId: basename(res.filePath),
           runId: opts.runId,
           rationale: `Exported ${reqs.length} requirements as ${opts.format}`,
         });

         return { path: res.filePath };
       },
     },
   };
 }

Index: apps/desktop/src/main/index.ts
===================================================================
--- apps/desktop/src/main/index.ts	
+++ apps/desktop/src/main/index.ts	
@@ -1,133 +1,133 @@
 import { join } from "node:path";
 import type { WorkflowRun } from "@reqflow/core";
 import { IPC_EVENTS } from "@reqflow/core/ipc";
 import { createFileStore } from "@reqflow/db";
 import { app, BrowserWindow, dialog, shell, type IpcMainInvokeEvent } from "electron";
 import { createHandlers } from "./handlers";
 import { registerIpc } from "./ipc";
 import { dataDir, loadDevEnv, uploadsDir } from "./paths";
 import { parseSmokeArg, runSmoke } from "./smoke";

 const smokeDir = parseSmokeArg(process.argv);

 // One instance per user: two processes writing the same SQLite file would corrupt the audit trail.
 if (!smokeDir && !app.requestSingleInstanceLock()) app.quit();

 function createWindow(): BrowserWindow {
   const win = new BrowserWindow({
     width: 1440,
     height: 900,
     minWidth: 1024,
     minHeight: 640,
     title: "ReqFlow",
     show: false,
     autoHideMenuBar: true,
     webPreferences: {
       preload: join(__dirname, "../preload/index.js"),
       contextIsolation: true,
       sandbox: true,
       nodeIntegration: false,
       // The smoke test renders off screen: it paints even when the display sleeps or the window
       // is covered, and never steals focus.
       offscreen: smokeDir !== null,
       // The off-screen window is never shown, so Chromium would treat the page as hidden and
       // throttle painting; screenshots would then lag behind the page.
       backgroundThrottling: smokeDir === null,
     },
   });
   win.once("ready-to-show", () => {
     if (!smokeDir) win.show();
   });

   // The window never navigates away from the app; http(s) links open in the user's browser.
   win.webContents.setWindowOpenHandler(({ url }) => {
     if (/^https?:\/\//.test(url)) void shell.openExternal(url);
     return { action: "deny" };
   });
   win.webContents.on("will-navigate", (event, url) => {
     const current = new URL(win.webContents.getURL());
     const next = new URL(url);
     if (next.origin !== current.origin || next.pathname !== current.pathname)
       event.preventDefault();
   });

   const devUrl = process.env.ELECTRON_RENDERER_URL;
   if (!app.isPackaged && devUrl) void win.loadURL(devUrl);
   else void win.loadFile(join(__dirname, "../renderer/index.html"));
   return win;
 }

 const isTrustedSender = (event: IpcMainInvokeEvent): boolean =>
   BrowserWindow.fromWebContents(event.sender) !== null &&
   event.senderFrame === event.sender.mainFrame;

 app.on("second-instance", () => {
   const [win] = BrowserWindow.getAllWindows();
   if (win) {
     if (win.isMinimized()) win.restore();
     win.focus();
   }
 });

 app.on("window-all-closed", () => {
   if (process.platform !== "darwin") app.quit();
 });

 void app.whenReady().then(() => {
   loadDevEnv();
   const dir = dataDir(smokeDir ? join(smokeDir, "data") : null);
   const files = createFileStore(uploadsDir(dir));
   const pushRunUpdate = (run: WorkflowRun) => {
     for (const win of BrowserWindow.getAllWindows()) {
       if (!win.isDestroyed()) {
         win.webContents.send(IPC_EVENTS.runUpdate, run);
       }
     }
   };

   registerIpc(
     createHandlers({
       files,
       dataDir: dir,
       pushRunUpdate,
       pickFile: async () => {
         const options: Electron.OpenDialogOptions = {
           title: "Choose an Excel or CSV file",
           properties: ["openFile"],
-          filters: [{ name: "Spreadsheets", extensions: ["xlsx", "csv"] }],
+          filters: [{ name: "Datasets", extensions: ["xlsx", "csv", "json"] }],
         };
         const parent = BrowserWindow.getFocusedWindow();
         const result = parent
           ? await dialog.showOpenDialog(parent, options)
           : await dialog.showOpenDialog(options);
         return result.canceled ? null : (result.filePaths[0] ?? null);
       },
       appInfo: () => ({
         version: app.getVersion(),
         platform: process.platform,
         dataDir: dir,
         isPackaged: app.isPackaged,
       }),
     }),
     isTrustedSender,
   );

   const win = createWindow();
   if (smokeDir) {
     void runSmoke(win, smokeDir, {
       files,
       samplesDir: join(app.getAppPath(), "../../data/samples"),
       bmwDir: join(app.getAppPath(), "../../data/raw"),
     }).then(
       (code) => app.exit(code),
       (err) => {
         console.error("[smoke] crashed:", err);
         app.exit(1);
       },
     );
   }

   app.on("activate", () => {
     if (BrowserWindow.getAllWindows().length === 0) createWindow();
   });
 });

Index: packages/blocks/src/ai-splitter/ai-splitter.ts
===================================================================
--- packages/blocks/src/ai-splitter/ai-splitter.ts	
+++ packages/blocks/src/ai-splitter/ai-splitter.ts	
@@ -1,135 +1,142 @@
 import { DATA_KEYS, countPipelineData, emptyPipelineData } from "@reqflow/core";
 import { defineBlock } from "@reqflow/engine";
 import {
   emptyMembership,
   emptyOutputs,
   evidenceIndex,
   primaryLayer,
   retainOrphans,
   select,
   validateInput,
   type PromptItem,
 } from "./evidence";
 import { priorityBranches, routePriority } from "./priority";
 import { analyzeRaw } from "./raw-analysis";
+import { selectRawOutputs } from "./raw-evidence";
 import {
   Assignments,
   ROUTING_SYSTEM,
   SplitterParams,
   batches,
   generate,
   validateIds,
 } from "./protocol";

 export const aiSplitterBlock = defineBlock({
   kind: "ai_splitter",
+  reroute(input, report) {
+    if (report.input.primaryLayer !== "records")
+      throw new Error("Routing corrections currently require a raw-record analytical report.");
+    validateInput(input);
+    return selectRawOutputs(input, new Map(report.assignments.map((a) => [a.itemId, Number(a.outputPortId.slice(4))])), report.branches.length).outputs;
+  },
   async run(inputs, rawParams, ctx) {
     ctx.signal.throwIfAborted();
     const params = SplitterParams.parse(rawParams);
     const ports = Object.keys(inputs);
     if (ports.some((port) => port !== "in"))
       throw new Error("AI Splitter supports only input port in");
     const input = Object.hasOwn(inputs, "in") ? inputs.in! : emptyPipelineData();
     validateInput(input);
     if (
       params.splitBy === "customer_priority" ||
       params.splitBy === "car_parts" ||
       (params.splitBy === "custom" && (input.records.length > 0 || !primaryLayer(input)))
     ) {
       return analyzeRaw(input, params, ctx);
     }
     if (params.splitBy === "priority") priorityBranches(params.branches);
     const counts = countPipelineData(input);
     ctx.log(
       `AI Splitter input: ${JSON.stringify(counts)}. ${params.branches.length} outputs, mode ${params.splitBy}.`,
     );
     ctx.progress(0, "Validating and preparing routing");
     const outputs = emptyOutputs(params.branches.length);
     const layer = primaryLayer(input);
     if (!layer) {
       if (input.sources.length) {
         outputs["out-0"] = input;
         ctx.log(
           `Source-only input: retained ${input.sources.length} sources as unclassified context on out-0; no LLM call.`,
         );
       } else ctx.log("Empty input; all output envelopes empty, no LLM call.");
       ctx.progress(1, "No primary items to route");
       return { status: "ok", outputs };
     }
     const index = evidenceIndex(input, ctx.log);
     const closures = new Map(input[layer].map((item) => [item.id, index.closure(layer, item.id)]));
     const items: PromptItem[] = input[layer].map((item) => {
       const context = index.context(closures.get(item.id)!);
       context[layer] = []; // Primary item is supplied once; dependencies are only contextual data.
       return { id: item.id, layer, item, context };
     });
     ctx.log(
       `Routing ${items.length} primary ${layer}; upstream evidence follows dependencies, not independent classification.`,
     );
     let routes: Map<string, number>;
     if (params.splitBy === "priority") routes = await routePriority(items, params, ctx);
     else {
       routes = new Map();
       const payload = (batch: PromptItem[]) => ({
         contract: "reqflow.ai-splitter.routing@1",
         mode: params.splitBy,
         branches: params.branches,
         instruction: params.splitBy === "custom" ? params.instruction : "",
         items: batch,
       });
       const groups = batches(items, payload);
       for (const [batchIndex, batch] of groups.entries()) {
         ctx.signal.throwIfAborted();
         ctx.log(`Routing batch ${batchIndex + 1}/${groups.length}: ${batch.length} primary items.`);
         const { object, model } = await generate(ctx, {
           system: ROUTING_SYSTEM,
           prompt: JSON.stringify(payload(batch)),
           schema: Assignments,
           tier: params.model,
         });
         const assignments = validateIds(
           object.assignments,
           batch.map((item) => item.id),
         );
         for (const entry of batch) {
           const assignment = assignments.get(entry.id)!;
           if (assignment.branchIndex >= params.branches.length) {
             throw new Error(
               `AI Splitter assignment ${entry.id} uses unknown branchIndex ${assignment.branchIndex}`,
             );
           }
           routes.set(entry.id, assignment.branchIndex);
           ctx.log(`Routed 1 primary item to out-${assignment.branchIndex}, model ${model}.`);
         }
         ctx.progress(
           routes.size / items.length,
           `Routed ${routes.size}/${items.length} primary items`,
         );
       }
     }
     ctx.signal.throwIfAborted();
     const memberships = params.branches.map(() => emptyMembership());
     for (const item of items) {
       const branchIndex = routes.get(item.id);
       if (branchIndex === undefined)
         throw new Error(`AI Splitter is missing a route for ${item.id}`);
       const membership = memberships[branchIndex];
       if (!membership)
         throw new Error(`AI Splitter route ${item.id} uses unknown branch ${branchIndex}`);
       const closure = closures.get(item.id)!;
       for (const key of DATA_KEYS) for (const id of closure[key]) membership[key].add(id);
     }
     retainOrphans(input, memberships, index, ctx.log);
     for (const [branchIndex, membership] of memberships.entries()) {
       if (membership[layer].size) outputs[`out-${branchIndex}`] = select(input, membership);
       ctx.log(
         `out-${branchIndex} (${params.branches[branchIndex]}): ${JSON.stringify(countPipelineData(outputs[`out-${branchIndex}`]!))}`,
       );
     }
     ctx.progress(
       1,
       `Routed ${items.length}/${items.length} primary items; supporting context retained`,
     );
     return { status: "ok", outputs };
   },
 });

