  DATA_KEYS,
  Finding,
  PipelineData,
  Requirement,
  Source,
  SourceRecord,
  Theme,
  type DataKey,
  type StoredFile,
} from "@reqflow/core";

const MAX_JSON_BYTES = 16 * 1024 * 1024;
